SELECT ?screenplayWriter ?screenplayWriterNobel ?nellySachsNobel WHERE {
  ?film wdt:P31 wd:Q11424;         # Instance of a film
        rdfs:label "The Night Hunter"@en;
        wdt:P58 ?screenplayWriter; # Has screenplay writer
        wdt:P144 ?sourceWork.      # Based on

  ?sourceWork wdt:P31 wd:Q47461344. # Source work is a novel

  OPTIONAL {
    ?screenplayWriter wdt:P166 ?award1.
    ?award1 wdt:P31 wd:Q37922.       # Award is Nobel Prize in Literature
    BIND(true AS ?screenplayWriterNobel)
  }
  OPTIONAL {
    wd:Q282465 wdt:P166 ?award2.    # Nelly Sachs's Wikidata item and awards
    ?award2 wdt:P31 wd:Q37922.
    BIND(true AS ?nellySachsNobel)
  }

  FILTER(!BOUND(?screenplayWriterNobel) || !BOUND(?nellySachsNobel))
}

