SELECT ?writer ?writerNobelWins ?nobelWinner WHERE {
  # Find writer of screenplay for The Night Hunter
  ?film wdt:P31 wd:Q11424;          # instance of film
        rdfs:label "The Night Hunter"@en;
        wdt:P58 ?writer.            # screenwriter
  # Check if the screenplay was based on a novel
  ?film wdt:P144 ?novel.
  ?novel wdt:P31 wd:Q8261.          # instance of novel
  # Check Nobel Prize in Literature for the writer and for Nelly Sachs
  OPTIONAL {
    ?writer wdt:P166 wd:Q37922.     # Nobel Prize in Literature
  }
  BIND(IF(EXISTS {?writer wdt:P166 wd:Q37922.}, 1, 0) AS ?writerNobelWins)

  # Nelly Sachs entity and Nobel literature award
  VALUES ?nobelWinner { wd:Q161581 } # Nelly Sachs
  OPTIONAL {
    wd:Q161581 wdt:P166 wd:Q37922.
  }
}
LIMIT 1

SELECT ?winner ?winnerBirthDate WHERE {
  ?tournament wdt:P31 wd:Q53420;     # tournament instance
             rdfs:label "1980 Lorraine Open"@en;
             wdt:P1346 ?winner.       # winner property

  ?winner wdt:P569 ?winnerBirthDate.  # date of birth
} LIMIT 1

